const emails = $input.all();
const SPAM_PATTERNS = ['shopee','lazada','tiki','grab','noreply','no-reply','donotreply','unsubscribe'];
const PROMO_KW = ['giảm giá','flash sale','khuyến mãi','ưu đãi','% off','sale','voucher','coupon'];

const preClassified = emails.map(item => {
  const e = item.json;
  const from = (e.from || '').toLowerCase();
  const subject = (e.subject || '').toLowerCase();
  const isSpam = SPAM_PATTERNS.some(p => from.includes(p));
  const isPromo = PROMO_KW.some(kw => subject.includes(kw));
  return {
    id: e.id,
    from: (e.from || '').replace(/<[^>]+>/g, '').trim(),
    subject: e.subject || '(no subject)',
    snippet: (e.snippet || e.textPlain || '').substring(0, 200),
    date: e.date,
    pre_category: isSpam ? 'spam' : isPromo ? 'promotion' : 'needs_ai_review'
  };
});

const needsReview = preClassified.filter(e => e.pre_category === 'needs_ai_review');
const obviousSpam = preClassified.filter(e => e.pre_category === 'spam');
const obviousPromo = preClassified.filter(e => e.pre_category === 'promotion');

console.log(`Pre-classify: ${obviousSpam.length} spam, ${obviousPromo.length} promo, ${needsReview.length} → DeepSeek`);

return [{ json: {
  all_emails: preClassified,
  needs_ai_review: needsReview,
  obvious_spam: obviousSpam,
  obvious_promo: obviousPromo,
  total: emails.length
} }];

const data = $input.first().json;
const emailsForAI = data.needs_ai_review;

if (emailsForAI.length === 0) {
  return [{ json: { skip_ai: true, ...data } }];
}

const emailList = emailsForAI.map((e, i) =>
  `[${i+1}] From: ${e.from}\nSubject: ${e.subject}\nSnippet: ${e.snippet}`
).join('\n---\n');

const systemPrompt = `Bạn là trợ lý quản lý email thông minh. Phân loại email vào: IMPORTANT (sếp/KH/deadline), WORK (công việc bình thường), PERSONAL (cá nhân/gia đình), NEWSLETTER (bản tin), SPAM (rác/quảng cáo). Chỉ trả về JSON array.`;

const userPrompt = `Phân loại các email sau:\n${emailList}\n\nJSON array format: [{"index":1,"category":"IMPORTANT","reason_vi":"lý do ngắn","action":"keep_urgent","priority":"high"}]\n\nAction values: keep_urgent/keep/archive/trash\nChỉ trả JSON, không giải thích.`;

return [{ json: { systemPrompt, userPrompt, emails_for_ai: emailsForAI, pre_data: data } }];

// Parse DeepSeek response (OpenAI-compatible format)
const dsResponse = $input.first().json;
const prevData = $('🤖 Chuẩn Bị DeepSeek Prompt').first().json;

let aiResults = [];
try {
  // DeepSeek trả về chuẩn OpenAI format
  const rawText = dsResponse.choices?.[0]?.message?.content || '[]';
  console.log('DeepSeek raw:', rawText.substring(0, 200));

  // Parse JSON - DeepSeek với json_object mode trả object hoặc array
  let parsed = JSON.parse(rawText);
  // Nếu trả về object có key là array
  if (!Array.isArray(parsed)) {
    parsed = Object.values(parsed).find(v => Array.isArray(v)) || [];
  }
  aiResults = parsed;
} catch(e) {
  console.error('DeepSeek parse error:', e.message);
  aiResults = (prevData.emails_for_ai || []).map((_, i) => ({
    index: i + 1, category: 'WORK', action: 'keep',
    priority: 'medium', reason_vi: 'Không thể parse AI response'
  }));
}

// Gắn kết quả AI vào email
const emailsForAI = prevData.emails_for_ai || [];
const aiClassified = aiResults.map(r => ({
  ...emailsForAI[r.index - 1],
  category: r.category,
  action: r.action,
  priority: r.priority,
  reason: r.reason_vi,
  classified_by: 'deepseek'
})).filter(Boolean);

// Merge với pre-classified
const preData = prevData.pre_data;
const allEmails = [
  ...aiClassified,
  ...(preData.obvious_spam || []).map(e => ({ ...e, category: 'SPAM', action: 'trash', priority: 'low', classified_by: 'rule' })),
  ...(preData.obvious_promo || []).map(e => ({ ...e, category: 'PROMOTION', action: 'archive', priority: 'low', classified_by: 'rule' }))
];

const grouped = {
  important: allEmails.filter(e => e.category === 'IMPORTANT'),
  work: allEmails.filter(e => e.category === 'WORK'),
  personal: allEmails.filter(e => e.category === 'PERSONAL'),
  newsletter: allEmails.filter(e => e.category === 'NEWSLETTER'),
  promotion: allEmails.filter(e => ['PROMOTION','promotion'].includes(e.category)),
  spam: allEmails.filter(e => ['SPAM','spam'].includes(e.category))
};

// Log usage (DeepSeek trả về usage stats)
const usage = dsResponse.usage || {};
console.log(`DeepSeek tokens: ${usage.prompt_tokens || 0} prompt + ${usage.completion_tokens || 0} completion`);

return [{ json: { grouped, all: allEmails, total: preData.total || allEmails.length, ds_usage: usage } }];

const data = $input.first().json;
const { grouped, total, ds_usage } = data;

const dateStr = new Date().toLocaleDateString('vi-VN', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric',
  timeZone: 'Asia/Ho_Chi_Minh'
});

const fmtSection = (arr, max = 3) => {
  if (!arr || arr.length === 0) return '_Không có_';
  const items = arr.slice(0, max).map((e, i) => {
    const tag = e.classified_by === 'deepseek' ? '🔵' : e.classified_by === 'ai' ? '🤖' : '⚡';
    const reason = e.reason ? ` _(${e.reason})_` : '';
    return `  ${i+1}. *${(e.subject||'').substring(0, 50)}*${reason}\n     📤 ${(e.from||'').substring(0, 38)} ${tag}`;
  }).join('\n');
  const more = arr.length > max ? `\n  _... +${arr.length - max} email_` : '';
  return items + more;
};

const urgentEmails = (grouped.important || []).filter(e => e.priority === 'high');
const urgentSection = urgentEmails.length > 0
  ? `\n🚨 *CẦN XỬ LÝ NGAY:*\n${fmtSection(urgentEmails)}`
  : '';

const cleanupCount = (grouped.spam?.length || 0) + (grouped.promotion?.length || 0);
const toTrashIds = (grouped.spam || []).map(e => e.id).filter(Boolean);
const toArchiveIds = (grouped.promotion || []).map(e => e.id).filter(Boolean);

// Token cost estimate (deepseek-chat: ~$0.14/1M input, $0.28/1M output)
const inputCost = ((ds_usage?.prompt_tokens || 0) / 1_000_000 * 0.14).toFixed(5);
const outputCost = ((ds_usage?.completion_tokens || 0) / 1_000_000 * 0.28).toFixed(5);
const costInfo = ds_usage?.total_tokens
  ? `\n💰 Token: ${ds_usage.total_tokens} (~$${(+inputCost + +outputCost).toFixed(5)})`
  : '';

const mainReport = `🔵 *BÁO CÁO EMAIL - DEEPSEEK AI*
📅 ${dateStr}
━━━━━━━━━━━━━━━━━━━━━━

📊 *Thống kê:*
• ⭐ Quan trọng: ${grouped.important?.length || 0}
• 💼 Công việc: ${grouped.work?.length || 0}
• 👤 Cá nhân: ${grouped.personal?.length || 0}
• 📰 Newsletter: ${grouped.newsletter?.length || 0}
• 🏷️ Khuyến mãi: ${grouped.promotion?.length || 0}
• 🗑️ Spam: ${grouped.spam?.length || 0}
• 📨 *Tổng: ${total} email*
${urgentSection}
━━━━━━━━━━━━━━━━━━━━━━

⭐ *QUAN TRỌNG:*
${fmtSection(grouped.important)}

💼 *CÔNG VIỆC:*
${fmtSection(grouped.work)}

👤 *CÁ NHÂN:*
${fmtSection(grouped.personal)}
━━━━━━━━━━━━━━━━━━━━━━
🧹 Tự động dọn: *${cleanupCount} email*
🔵 Phân tích bởi DeepSeek${costInfo}`;

return [{ json: { mainReport, toTrashIds, toArchiveIds, grouped, total } }];

const report = $('📊 Tạo Báo Cáo DeepSeek').first().json;
const toTrashIds = report.toTrashIds || [];
const toArchiveIds = report.toArchiveIds || [];

if (toTrashIds.length === 0 && toArchiveIds.length === 0) {
  return [{ json: { nothing_to_clean: true } }];
}

const tasks = [
  ...toTrashIds.map(id => ({ emailId: id, action: 'trash' })),
  ...toArchiveIds.map(id => ({ emailId: id, action: 'archive' }))
];
return tasks.map(t => ({ json: t }));

const report = $('📊 Tạo Báo Cáo DeepSeek').first().json;
console.log(`✅ V4 DeepSeek completed. Total: ${report.total}, Trashed: ${report.toTrashIds?.length || 0}, Archived: ${report.toArchiveIds?.length || 0}`);
return [{ json: {
  status: 'completed',
  workflow_version: 'v4-deepseek',
  total_processed: report.total,
  trashed: report.toTrashIds?.length || 0,
  archived: report.toArchiveIds?.length || 0,
  finished_at: new Date().toISOString()
} }];
